WITH deduped AS (SELECT * FROM orders QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY shipping_fee DESC NULLS FIRST, id) = 1) SELECT channel, status, DATE_TRUNC('YEAR', order_date) AS year_start, COUNT(DISTINCT store_id) AS distinct_store_ids, SIZE(COLLECT_SET(status)) AS num_status, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM deduped GROUP BY channel, status, DATE_TRUNC('YEAR', order_date) ORDER BY channel NULLS FIRST;
